data: {"type":"response.output_text.done","content_index":0,"item_id":"msg_06f67fb436896d87016aecc01abb6887d29f509416a03b5be3","logprobs":[],"output_index":0,"sequence_number":893,"text":"<title>Bean &amp; Bloom</title>\n<meta name=\"idea\" content=\"A welcoming coffee menu with quick category browsing and a live order summary\">\n<nav aria-label=\"Main navigation\">\n  <ul>\n    <li><strong>Bean &amp; Bloom</strong></li>\n  </ul>\n  <ul>\n    <li><a href=\"#menu\" aria-current=\"page\">Menu</a></li>\n    <li><a href=\"#orders\" data-action=\"@orders: Order history screen for Bean & Bloom coffee shop\">Orders</a></li>\n    <li><a href=\"#account\" data-action=\"@account: Customer account screen for Bean & Bloom coffee shop\">Account</a></li>\n  </ul>\n</nav>\n<main>\n  <h1>Good morning</h1>\n  <p>Your neighborhood coffee, made just right.</p>\n  <label for=\"category\">Browse the menu</label>\n  <select id=\"category\">\n    <option value=\"all\">All drinks</option>\n    <option value=\"espresso\">Espresso</option>\n    <option value=\"tea\">Tea</option>\n  </select>\n  <section id=\"menu\" aria-label=\"Menu\">\n    <article data-category=\"espresso\">\n      <h2>Honey Oat Latte</h2>\n      <p>Espresso, steamed oat milk, a touch of honey.</p>\n      <p><strong>$5.25</strong></p>\n      <button data-action=\"@honey-oat-latte: Details and size options for the Honey Oat Latte at Bean & Bloom\">Details</button>\n      <button class=\"add\" data-price=\"5.25\">Add to order</button>\n    </article>\n    <article data-category=\"espresso\">\n      <h2>Maple Cold Brew</h2>\n      <p>Slow-steeped coffee with maple cream.</p>\n      <p><strong>$4.75</strong></p>\n      <button data-action=\"@maple-cold-brew: Details and size options for Maple Cold Brew at Bean & Bloom\">Details</button>\n      <button class=\"add\" data-price=\"4.75\">Add to order</button>\n    </article>\n    <article data-category=\"tea\">\n      <h2>Matcha Cloud</h2>\n      <p>Stone-ground matcha with vanilla foam.</p>\n      <p><strong>$5.50</strong></p>\n      <button data-action=\"@matcha-cloud: Details and size options for Matcha Cloud at Bean & Bloom\">Details</button>\n      <button class=\"add\" data-price=\"5.50\">Add to order</button>\n    </article>\n  </section>\n  <article>\n    <h2>Your order</h2>\n    <p><span id=\"count\">0</span> items · <strong id=\"total\">$0.00</strong></p>\n    <button id=\"clear\">Clear order</button>\n    <button data-action=\"@order-checkout: Checkout screen for a Bean & Bloom order with drinks in the cart\">Checkout</button>\n  </article>\n  <footer>\n    <nav aria-label=\"Quick links\">\n      <a href=\"#menu\">Menu</a>\n      <a href=\"#orders\" data-action=\"@orders: Order history screen for Bean & Bloom coffee shop\">Orders</a>\n      <a href=\"#account\" data-action=\"@account: Customer account screen for Bean & Bloom coffee shop\">Account</a>\n    </nav>\n  </footer>\n</main>\n<script>\nlet count=0,total=0;\nconst update=()=>{document.querySelector(\"#count\").textContent=count.toLocaleString();document.querySelector(\"#total\").textContent=\"$\"+total.toFixed(2)};\ndocument.querySelectorAll(\".add\").forEach(b=>b.addEventListener(\"click\",()=>{count++;total+=Number(b.dataset.price);update()}));\ndocument.querySelector(\"#clear\").addEventListener(\"click\",()=>{count=0;total=0;update()});\ndocument.querySelector(\"#category\").addEventListener(\"change\",e=>document.querySelectorAll(\"#menu article\").forEach(a=>a.hidden=e.target.value!==\"all\"&&a.dataset.category!==e.target.value));\n</script>"}

